mapper.select:
with table1 as ( select contract_code , to_char(create_time, 'YYYYMM')::int as periods , sum(ta_amount) ta_amount from eg_contract_ta_amount ecta where 1=1
and contract_code = #{param.contractCode}
group by contract_code ,periods order by contract_code ), table2 as ( select t1.contract_code, t1.periods, sum(t2.ta_amount) as ta_balance from table1 t1 inner join table1 t2 on t1.contract_code=t2.contract_code and t1.periods=t2.periods where 1=1
and t1.contract_code = #{param.contractCode}
group by t1.contract_code, t1.periods order by t1.contract_code, t1.periods ) select t.* from ( select erp.periods, erp.plan_date as plan_date_period, erp.rent_amount, erp.principal_amount as principalAmount, erp.interest_amount as interestAmount, erp.actual_repayment_principal_amount, erp.actual_repayment_interes_amount,
coalesce(erp.actual_repayment_principal_amount,0)+coalesce(erp.actual_repayment_interes_amount,0) as actual_repayment_rent_amount, erp.actual_repayment_date, erp.ebank_serial_number as bankNum, erp.settlement_way as settlementTerms, erp.adjustment_amount, (erp.change_after_ending_amortized_cost-erp.ending_amortized_cost) as ending_amortized_cost_balance, (erp.change_after_rental_income-erp.rental_income) as rental_income_balance, erp.create_time, ta.ta_balance from eg_repayment_plan erp left join table2 ta on erp.contract_code = ta.contract_code and to_char(erp.plan_date, 'YYYYMM')::int=ta.periods where 1 = 1 and erp.del_flag = '0'
and erp.contract_code = #{param.contractCode}
and to_char(erp.create_time, 'yyyy-MM-dd') = to_char(to_date(#{param.versionDate}, 'YYYY-MM-DD'), 'YYYY-MM-DD')
union all select erph.periods, erph.plan_date as plan_date_period, erph.rent_amount, erph.principal_amount as principalAmount, erph.interest_amount as interestAmount, erph.actual_repayment_principal_amount, erph.actual_repayment_interes_amount, coalesce(erph.actual_repayment_principal_amount,0)+coalesce(erph.actual_repayment_interes_amount,0) as actual_repayment_rent_amount, erph.actual_repayment_date, erph.ebank_serial_number as bankNum, erph.settlement_way as settlementTerms, erph.adjustment_amount, (erph.change_after_ending_amortized_cost-erph.ending_amortized_cost) as ending_amortized_cost_balance, (erph.change_after_rental_income-erph.rental_income) as rental_income_balance, erph.create_time , ta.ta_balance from eg_repayment_plan_his erph left join table2 ta on erph.contract_code = ta.contract_code and to_char(erph.plan_date, 'YYYYMM')::int=ta.periods where 1 = 1 and erph.del_flag = '0'
and erph.contract_code = #{param.contractCode}
and to_char(erph.create_time, 'yyyy-MM-dd') = to_char(to_date(#{param.versionDate}, 'YYYY-MM-DD'), 'YYYY-MM-DD')
) t where 1=1 and t.periods is not null order by to_char(t.create_time, 'YYYY-MM-DD') desc,t.periods asc,t.plan_date_period asc

select t.* from( select erp.periods, erp.plan_date as plan_date_period, erp.rent_amount, erp.principal_amount as principalAmount, erp.interest_amount as interestAmount, erp.actual_repayment_principal_amount, erp.actual_repayment_interes_amount, coalesce(erp.actual_repayment_principal_amount,0)+coalesce(erp.actual_repayment_interes_amount,0) as actual_repayment_rent_amount, erp.actual_repayment_date, erp.ebank_serial_number as bankNum, erp.settlement_way as settlementTerms, erp.create_time from eg_repayment_plan erp where 1 = 1 and erp.del_flag = '0'
and erp.contract_code = #{param.contractCode}
and to_char(erp.create_time, 'yyyy-MM-dd') = to_char(to_date(#{param.versionDate}, 'YYYY-MM-DD'), 'YYYY-MM-DD')
union all select erph.periods, erph.plan_date as plan_date_period, erph.rent_amount, erph.principal_amount as principalAmount, erph.interest_amount as interestAmount, erph.actual_repayment_principal_amount, erph.actual_repayment_interes_amount, coalesce(erph.actual_repayment_principal_amount,0)+coalesce(erph.actual_repayment_interes_amount,0) as actual_repayment_rent_amount, erph.actual_repayment_date, erph.ebank_serial_number as bankNum, erph.settlement_way as settlementTerms, erph.create_time from eg_repayment_plan_his erph where 1 = 1 and erph.del_flag = '0'
and erph.contract_code = #{param.contractCode}
and to_char(erph.create_time, 'yyyy-MM-dd') = to_char(to_date(#{param.versionDate}, 'YYYY-MM-DD'), 'YYYY-MM-DD')
) t where 1=1 and t.periods is not null order by t.periods asc,t.plan_date_period asc
